//! The palette file and the one place a stylesheet reaches the display.
//!
//! `~/.config/widgets/palette.css`, generated by `palette sync`, defines the
//! `@palette_*` named colors every widgets stylesheet references. It is loaded
//! with a built-in fallback so a missing file never stops a widget.
//!
//! Everything a widget draws hangs off a single [`gtk4::CssProvider`] that this
//! module hands back to [`crate::theme`]. Keeping the provider around is what
//! lets a running widget reread the palette and restyle itself — see
//! [`crate::theme::init`].

use std::path::PathBuf;

/// Where the palette and the user's own widget sheets live, under `$HOME`.
const CONFIG_DIR: &str = ".config/widgets";

/// The generated palette's name inside that directory.
const PALETTE_FILE: &str = "palette.css";

pub(crate) const FALLBACK: &str = r#"
@define-color palette_bg #19120c;
@define-color palette_fg #e8e1dd;
@define-color palette_cursor #ffc079;
@define-color palette_color0 #261e15;
@define-color palette_color1 #ff8a70;
@define-color palette_color2 #a2b275;
@define-color palette_color3 #d6a163;
@define-color palette_color4 #5eb5e1;
@define-color palette_color5 #ca9dc7;
@define-color palette_color6 #79b7a8;
@define-color palette_color7 #ccc5c2;
@define-color palette_color8 #776b5f;
@define-color palette_color9 #ffcbc0;
@define-color palette_color10 #cede9e;
@define-color palette_color11 #ffcf99;
@define-color palette_color12 #a8deff;
@define-color palette_color13 #f9c8f4;
@define-color palette_color14 #a4e4d3;
@define-color palette_color15 #fcf5f4;
"#;

/// `$HOME/.config/widgets`, where both files below live.
pub(crate) fn config_dir() -> Option<PathBuf> {
    let mut path = PathBuf::from(std::env::var_os("HOME")?);
    path.push(CONFIG_DIR);
    Some(path)
}

/// The palette stylesheet's path, `$HOME/.config/widgets/palette.css`.
pub(crate) fn palette_file() -> Option<PathBuf> {
    Some(config_dir()?.join(PALETTE_FILE))
}

/// A widget's own sheet, `$HOME/.config/widgets/<name>.css`. When the user places
/// one it replaces the sheet the widget ships and is watched for hot-reload,
/// mirroring the palette hot-reload that already exists for `palette.css`.
pub(crate) fn sheet_file(name: &str) -> Option<PathBuf> {
    Some(config_dir()?.join(format!("{name}.css")))
}

/// The palette stylesheet, or the built-in fallback when it is missing.
pub(crate) fn palette_css() -> String {
    palette_file()
        .and_then(|path| std::fs::read_to_string(path).ok())
        .unwrap_or_else(|| FALLBACK.to_string())
}

/// The `palette_fg` colour from the palette stylesheet, as a GDK colour.
///
/// A widget that rasterizes a bitmap (an icon, say) cannot pull its colour from
/// the stylesheet cascade the way a label does, so it reads the token here
/// instead. The built-in fallback is used when the file is missing, so this is
/// `None` only when the value itself cannot be parsed — never because the user
/// has not run `palette sync` yet.
pub fn palette_fg_rgba() -> Option<gtk4::gdk::RGBA> {
    let value = named_color(&palette_css(), "palette_fg")?;
    gtk4::gdk::RGBA::parse(value.as_str()).ok()
}

/// Pull one `@define-color <name> <value>;` declaration out of a stylesheet
/// document.
fn named_color(sheet: &str, name: &str) -> Option<String> {
    let prefix = format!("@define-color {name} ");
    sheet.lines().find_map(|line| {
        let rest = line.trim().strip_prefix(&prefix)?;
        let value = rest.trim().trim_end_matches(';').trim();
        (!value.is_empty()).then(|| value.to_string())
    })
}

/// Register a stylesheet document on the display and return its provider.
///
/// One provider holds the whole document so the cascade inside it is decided
/// by source order instead of by registration order.
pub(crate) fn provider(document: &str) -> gtk4::CssProvider {
    let provider = gtk4::CssProvider::new();
    provider.load_from_data(document);
    if let Some(display) = gtk4::gdk::Display::default() {
        gtk4::style_context_add_provider_for_display(
            &display,
            &provider,
            gtk4::STYLE_PROVIDER_PRIORITY_APPLICATION,
        );
    }
    provider
}
